const brands = $('Get Last Month Brand Stats').all().map(b => b.json);
const revenue = $('Get Last Month Revenue').first().json;
const reviews = $('Get Last Month Reviews').first().json;
const sheriff = $('Get Sheriff Actions Last Month').first().json;
const creds = $('Get WhatsApp Credentials').first().json;

const lastMonth = new Date();
lastMonth.setMonth(lastMonth.getMonth() - 1);
const monthName = lastMonth.toLocaleDateString('en-IN', { month: 'long', year: 'numeric' });

const totalLeads = brands.reduce((a, b) => a + parseInt(b.leads || 0), 0);
const totalConverted = brands.reduce((a, b) => a + parseInt(b.converted || 0), 0);
const overallRate = totalLeads > 0 ? ((totalConverted / totalLeads) * 100).toFixed(1) : '0';

let msg = `📊 MONTHLY REPORT — ${monthName}\n`;
msg += `${'='.repeat(30)}\n\n`;
msg += `💼 OVERALL PERFORMANCE:\n`;
msg += `• Total Leads: ${totalLeads}\n`;
msg += `• Converted: ${totalConverted} (${overallRate}%)\n`;
msg += `• Revenue: Rs ${parseInt(revenue.total_revenue || 0).toLocaleString('en-IN')}\n`;
msg += `• Transactions: ${revenue.total_transactions || 0}\n\n`;

if (brands.length > 0) {
  msg += `🏢 BRAND BREAKDOWN:\n`;
  brands.forEach(b => {
    msg += `${b.brand}: ${b.leads} leads → ${b.converted} converted (${b.conv_rate}%)\n`;
  });
  msg += `\n`;
}

msg += `⭐ GMB REVIEWS:\n`;
msg += `• New reviews: ${reviews.new_reviews || 0}\n`;
msg += `• Avg rating: ${reviews.avg_rating || 'N/A'} ★\n\n`;

msg += `🤖 AI SHERIFF:\n`;
msg += `• Auto-actions taken: ${sheriff.executed || 0}\n\n`;

msg += `📱 Full report: https://leados-app.abmgroups.org`;

return [{ json: { message: msg, phone_number_id: creds.phone_number_id, wa_access_token: creds.wa_access_token } }];
